INSERT INTO `calendar_event_details` (`id`, `event_date`, `category_id`, `title`, `content`) VALUES
(1, '2026-03-01', 6, '三月份部門聚餐', '地點：台北市信義區王品牛排，全員參加慶祝專案達成。'),
(2, '2026-03-15', 7, 'Q1 財報初步結算', '各部門繳交第一季預算執行與財務報表。'),
(3, '2026-03-20', 8, '春季新品線上發表會', '透過 YouTube 頻道直播向全球發表年度旗艦商品。'),
(4, '2026-04-10', 9, 'AI 雲端技術研討會', '邀請外部專家分享生成式 AI 在企業內部的應用案例。'),
(5, '2026-04-22', 33, '世界地球日環保志工', '組織員工前往淡水河畔進行淨灘與垃圾分類活動。'),
(6, '2026-05-15', 10, '公司春季國內員工旅遊', '三天兩夜花蓮太魯閣與東大門夜市參訪。'),
(7, '2026-05-25', 11, '新進員工資安基礎訓練', '為期兩天的資訊安全與個資保護線上授課。'),
(8, '2026-06-08', 12, '年度股東常會', '於台北國際會議中心舉行，報告去年營運成果及股利分配。'),
(9, '2026-06-18', 13, '伺服器機房定期維護', '凌晨 00:00 至 04:00 進行主機系統更新與斷電演練。'),
(10, '2026-07-01', 14, '新 ERP 系統上線驗收', '財務與供應鏈模組正式切換，顧問團隊現場支援。'),
(11, '2026-07-15', 15, '台北國際電腦展參展', '南港展覽館攤位搭建與展品擺設，迎接國際買主。'),
(12, '2026-08-05', 16, '全廠區消防防災演練', '模擬地震發生及火災逃生路線演練，全員必須配合。'),
(13, '2026-08-20', 21, 'Q3 營運策略共識會議', '高階主管於宜蘭礁溪老爺酒店進行兩天閉門會議。'),
(14, '2026-09-10', 23, '中秋節聯合促銷檔期', '線上商城全面啟動特惠折扣與滿額贈禮活動。'),
(15, '2026-09-22', 22, '日本大客戶年度拜訪', '董事長率領業務團隊前往東京總部拜訪核心策略夥伴。'),
(16, '2026-10-05', 24, '企業永續報告書發表', '向外界公布本年度 ESG 實踐成果與減碳數據。'),
(17, '2026-10-18', 29, '公司秋季趣味運動會', '於板橋體育場舉辦大隊接力、拔河與趣味競賽。'),
(18, '2026-11-05', 30, '當代藝術特展贊助參觀', '包場台北市立美術館，邀請員工與家屬免費參觀。'),
(19, '2026-11-20', 32, '愛心捐血公益日', '捐血車駛入公司大門口，號召同仁挽袖捐熱血。'),
(20, '2026-12-10', 37, '次年度營運計畫擬定', '各部門主管提交明年 KPI 目標與資源需求表。'),
(21, '2026-12-28', 17, '年度大型感恩尾牙宴', '於台北萬豪酒店舉辦，席開 80 桌並有抽獎活動。'),
(22, '2027-01-15', 38, '年度預算審查會議', '董事會審核通過次年度各單位資本支出與預算案。'),
(23, '2027-02-05', 18, '新春開工團拜與春酒', '農曆年後第一個上班日，發放開工紅包並舉行春酒。'),
(24, '2027-03-10', 39, '第一季法人說明會', '向各大法人機構說明開春後之營運展望與接單狀況。'),
(25, '2027-04-12', 40, '新一代晶片試產驗證', '晶圓廠投片測試，工程團隊駐廠監控良率。'),
(26, '2027-05-18', 41, 'ISO 9001 品質系統稽核', '第三方認證機構進行為期三天的年度複審。'),
(27, '2027-06-15', 42, '辦公室網路設備全面升級', '更換全棟大樓之 Wi-Fi 7 無線路由器與核心交換器。'),
(28, '2027-07-20', 43, '空調與無塵室定期消毒', '配合廠區夏季保養進行全面清潔與濾網更換。'),
(29, '2027-08-12', 44, '大樓聯合消防安全檢查', '轄區消防分隊到場進行消防栓與排煙系統測試。'),
(30, '2027-09-14', 45, '高階資安社交工程防範特訓', '邀請刑事局防詐專家蒞臨演講與防範宣導。'),
(31, '2027-10-25', 46, '核心技術發明專利申請', '研發部門完成新演算法之國際專利文件送件。'),
(32, '2027-11-15', 48, '與矽谷新創簽署 M&A 協議', '跨國技術合作與策略結盟記者會。'),
(33, '2027-12-20', 50, '年度 VIP 客戶答謝晚宴', '邀請全球前十大核心客戶齊聚台北迎新年。'),
(34, '2028-01-10', 51, '全球供應商夥伴大會', '頒發年度最佳供應商獎項並佈局明年產能規劃。'),
(35, '2028-02-22', 52, '亞太區經銷商年會', '於新加坡舉辦區域業務檢討與新品教育訓練。'),
(36, '2028-03-18', 53, '跨國研發團隊視訊連線', '台灣、矽谷、慕尼黑三地同步進行技術同步會議。'),
(37, '2028-04-20', 54, '高階管理層策略共識營', '為期三天兩夜的未來五年願景藍圖規劃。'),
(38, '2028-05-10', 55, '全球卓越員工表揚大會', '頒發年度傑出貢獻獎與百萬研發獎金。'),
(39, '2028-06-05', 21, '年中業務檢討會議', '各區業務總監報告上半年業績達成率與下半年追趕計畫。'),
(40, '2028-07-12', 22, '歐美重點通路商拜訪', '拜訪美國西岸各大核心零售通路與技術合作夥伴。'),
(41, '2028-08-15', 23, '下半年旗艦新品預熱行銷', '社群媒體與科技媒體全面展開造勢宣傳。'),
(42, '2028-09-18', 25, '財經雜誌封面故事專訪', '接受商業周刊專訪關於企業數位轉型之路。'),
(43, '2028-10-12', 26, '綠色能源採購合作備忘錄簽署', '與台電及綠電供應商簽訂長期購電協議。'),
(44, '2028-11-08', 27, '研發部門秋季戶外烤肉聚會', '於新北市烏來溫泉度假村舉辦部門凝聚向心力活動。'),
(45, '2028-12-05', 28, '年終聯合慶生同樂會', '為第四季壽星舉辦慶生派對並發放生日禮金。'),
(46, '2029-01-08', 35, '資深經理榮譽退休歡送會', '感謝服務滿 25 年之協理榮退並舉辦感恩茶會。'),
(47, '2029-02-19', 36, '年度人事晉升佈達', '公佈新一年度各級主管晉升名單與組織架構調整。'),
(48, '2029-03-25', 19, '偏鄉學童公益捐贈活動', '前往花蓮偏遠小學捐贈平板電腦與數位圖書。'),
(49, '2029-04-18', 20, '環境永續 ISO 14001 稽核', '溫室氣體盤查與碳足跡認證實地審查。'),
(50, '2029-05-12', 10, '公司成立週年慶祝大會', '歡慶公司創立紀念日，全體員工享用午茶餐點與紀念品發放。');
