INSERT INTO `pma__bookmark` (`id`, `dbase`, `user`, `label`, `query`) VALUES
(1, 'lee', '', '更新帳號與會員資料表ID為1存貨0亡', 'UPDATE members\r\nSET status = 1,\r\n    living_status = \'存\'\r\nWHERE id IN (1, 2, 3, 38, 39, 40, 41);\r\n\r\nUPDATE account\r\nSET status = \'1\'\r\nWHERE id IN (1, 2, 3, 38, 39, 40, 41);\r\n'),
(2, 'lee', '', '更新會員資料_用id對姓名', 'UPDATE members\r\nSET name = \'李明輝\'\r\nWHERE id = 1;\r\n\r\nUPDATE members\r\nSET name = \'李美麗\'\r\nWHERE id = 2;\r\n'),
(3, 'lee', '', '查詢所有2016年地號的地價', 'SELECT record_date, section_name, land_number, posted_land_value\r\nFROM land_price\r\nWHERE record_date = \'2026-01\'\r\n  AND ( (section_name = \'義水段\' AND land_number IN (\'0855-0000\',\'0861-0000\',\'0911-0000\',\'0930-0000\',\r\n                                                     \'0934-0000\',\'0979-0000\',\'0980-0000\',\'0984-0000\',\r\n                                                     \'0987-0000\',\'0989-0000\',\'0995-0000\',\'1035-0000\',\r\n                                                     \'1040-0000\'))\r\n       OR (section_name = \'水美東段\' AND land_number IN (\'0191-0000\',\'0192-0000\',\'0193-0000\',\r\n                                                        \'0194-0000\',\'0195-0000\',\'0565-0000\')) );\r\n'),
(4, 'lee', '', '查詢所有2016年所有地號的地價', 'SELECT record_date, section_name, land_number, posted_land_value, declared_land_value, land_area\r\nFROM land_price\r\nWHERE record_date LIKE \'2026-%\'\r\n  AND (\r\n       (section_name = \'義水段\' AND land_number IN (\r\n         \'0855-0000\',\'0861-0000\',\'0911-0000\',\'0930-0000\',\r\n         \'0934-0000\',\'0979-0000\',\'0980-0000\',\'0984-0000\',\r\n         \'0987-0000\',\'0989-0000\',\'0995-0000\',\'1035-0000\',\r\n         \'1040-0000\'\r\n       ))\r\n       OR\r\n       (section_name = \'水美東段\' AND land_number IN (\r\n         \'0191-0000\',\'0192-0000\',\'0193-0000\',\r\n         \'0194-0000\',\'0195-0000\',\'0565-0000\'\r\n       ))\r\n     );\r\n'),
(5, 'lee', '', '刪除所有2016年所有地號的地價', 'DELETE FROM land_price\r\nWHERE record_date LIKE \'2026-%\'\r\n  AND (\r\n       (section_name = \'義水段\' AND land_number IN (\r\n         \'0855-0000\',\'0861-0000\',\'0911-0000\',\'0930-0000\',\r\n         \'0934-0000\',\'0979-0000\',\'0980-0000\',\'0984-0000\',\r\n         \'0987-0000\',\'0989-0000\',\'0995-0000\',\'1035-0000\',\r\n         \'1040-0000\'\r\n       ))\r\n       OR\r\n       (section_name = \'水美東段\' AND land_number IN (\r\n         \'0191-0000\',\'0192-0000\',\'0193-0000\',\r\n         \'0194-0000\',\'0195-0000\',\'0565-0000\'\r\n       ))\r\n     );\r\n'),
(6, 'lee', '', '查除了正式地號以外的資料價格要刪除', 'SELECT * \r\nFROM `land_price` \r\nWHERE `land_number` NOT IN (\r\n    \'0855-0000\', \'0856-0000\', \'0861-0000\', \'0865-0000\', \'0868-0000\', \r\n    \'0869-0000\', \'0565-0000\', \'0191-0000\', \'0192-0000\', \'0193-0000\', \r\n    \'0194-0000\', \'0195-0000\', \'0176-0000\', \'0385-0000\', \'0864-0000\', \r\n    \'0871-0000\', \'0876-0000\', \'0909-0000\', \'0911-0000\', \'0930-0000\', \r\n    \'0934-0000\', \'0979-0000\', \'0980-0000\', \'0984-0000\', \'0987-0000\', \r\n    \'0989-0000\', \'0995-0000\', \'1035-0000\', \'1040-0000\'\r\n);'),
(7, 'lee', 'root', '查詢所有2016年所有地號的地價', 'SELECT * FROM `land_price` WHERE 1'),
(8, 'lee', 'root', '查詢所有2016年地號的地價', 'SELECT * FROM `land_price` WHERE 1'),
(9, 'lee', 'root', '查詢所有2016年所有地號的地價', 'SELECT * FROM `land_price` WHERE 1');
